import{az as a,P as e,Q as l,aQ as t}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const F=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"构建工具/babel/index.md","filePath":"构建工具/babel/index.md","lastUpdated":1785343326000}'),o={name:"构建工具/babel/index.md"};function n(r,s,p,c,d,i){return e(),l("div",null,[...s[0]||(s[0]=[t(`<h2 id="babel-简介" tabindex="-1">Babel 简介 <a class="header-anchor" href="#babel-简介" aria-label="Permalink to “Babel 简介”">​</a></h2><p>Babel 是一个广泛使用的 JavaScript 编译器，主要作用是将 ES6+（ES2015 及更高版本）的代码转换为向后兼容的 JavaScript 语法，以便在旧版浏览器或环境中运行。除了语法转换，Babel 还支持 JSX 转换、TypeScript 转换等功能。</p><p>Babel 最初名为 6to5，于 2014 年发布，后改名为 Babel。它是 React 生态和现代前端工程化的重要基石。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><p>Babel 的核心能力包括：</p><ul><li><strong>语法转换</strong>：将新语法（如箭头函数、可选链、装饰器）转换为旧语法</li><li><strong>Polyfill</strong>：为旧环境补充缺失的内置 API（如 <code>Promise</code>、<code>Array.includes</code>）</li><li><strong>JSX 转换</strong>：将 JSX 转换为 <code>React.createElement</code> 或新的 <code>jsx</code> 运行时调用</li><li><strong>TypeScript stripping</strong>：去除 TypeScript 类型注解（<code>@babel/preset-typescript</code>）</li></ul><h2 id="preset-与-plugin-机制" tabindex="-1">Preset 与 Plugin 机制 <a class="header-anchor" href="#preset-与-plugin-机制" aria-label="Permalink to “Preset 与 Plugin 机制”">​</a></h2><p>Babel 7+ 通过 preset（预设）和 plugin（插件）的组合来配置转换规则。Preset 是一组 plugin 的集合，方便开箱即用。</p><p>常见的 preset 包括：</p><ul><li><code>@babel/preset-env</code>：根据目标浏览器自动选择需要的语法转换</li><li><code>@babel/preset-react</code>：转换 JSX</li><li><code>@babel/preset-typescript</code>：去除 TypeScript 类型</li></ul><h3 id="配置示例" tabindex="-1">配置示例 <a class="header-anchor" href="#配置示例" aria-label="Permalink to “配置示例”">​</a></h3><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">presets</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> [</span></span>
<span class="line"><span style="color:#89DDFF;">    [</span></span>
<span class="line"><span style="color:#89DDFF;">      &quot;</span><span style="color:#C3E88D;">@babel/preset-env</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">      {</span></span>
<span class="line"><span style="color:#89DDFF;">        &quot;</span><span style="color:#FFCB6B;">targets</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">&gt; 0.25%, not dead</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">        &quot;</span><span style="color:#FFCB6B;">useBuiltIns</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">usage</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">        &quot;</span><span style="color:#FFCB6B;">corejs</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 3</span></span>
<span class="line"><span style="color:#89DDFF;">      }</span></span>
<span class="line"><span style="color:#89DDFF;">    ],</span></span>
<span class="line"><span style="color:#89DDFF;">    [</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">@babel/preset-react</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> {</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#FFCB6B;">runtime</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">automatic</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;"> }],</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#C3E88D;">@babel/preset-typescript</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">  ]</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h2 id="babel-preset-env-详解" tabindex="-1">@babel/preset-env 详解 <a class="header-anchor" href="#babel-preset-env-详解" aria-label="Permalink to “@babel/preset-env 详解”">​</a></h2><p><code>@babel/preset-env</code> 是 Babel 最核心的预设，它根据 <code>browserslist</code> 配置的目标浏览器，智能决定需要启用哪些转换和 polyfill。</p><p>关键配置项：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><code>targets</code></td><td>目标浏览器，如 <code>&quot;&gt; 1%&quot;</code>、<code>&quot;last 2 versions&quot;</code></td></tr><tr><td><code>useBuiltIns</code></td><td>polyfill 注入方式：<code>false</code>、<code>entry</code>、<code>usage</code></td></tr><tr><td><code>corejs</code></td><td>指定 core-js 版本，通常为 <code>3</code></td></tr><tr><td><code>modules</code></td><td>模块转换方式：<code>commonjs</code>、<code>false</code>（保留 ESM）</td></tr></tbody></table><p><code>useBuiltIns: &quot;usage&quot;</code> 是推荐做法，它会按文件实际使用到的 API 精确注入 polyfill，避免冗余。</p><h2 id="polyfill-方案演进" tabindex="-1">Polyfill 方案演进 <a class="header-anchor" href="#polyfill-方案演进" aria-label="Permalink to “Polyfill 方案演进”">​</a></h2><p>Babel 的 polyfill 方案经历了重要变化：</p><ul><li><strong>@babel/polyfill（已废弃）</strong>：早期方案，一次性引入全部 polyfill，包体过大</li><li><strong>core-js + regenerator-runtime</strong>：现代推荐方案，配合 <code>useBuiltIns: &quot;usage&quot;</code> 按需引入</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#FFCB6B;">npm</span><span style="color:#C3E88D;"> install</span><span style="color:#C3E88D;"> core-js</span><span style="color:#C3E88D;"> regenerator-runtime</span></span></code></pre></div><p>安装 <code>@babel/preset-env</code> 并配置 <code>corejs: 3</code> 后，Babel 会自动在需要的文件顶部插入对应的 polyfill import，无需手动引入。</p><h2 id="browserslist-配置" tabindex="-1">browserslist 配置 <a class="header-anchor" href="#browserslist-配置" aria-label="Permalink to “browserslist 配置”">​</a></h2><p>browserslist 是一个共享的目标浏览器配置，多个工具（Babel、Autoprefixer、ESLint）可复用同一份配置。通常在 <code>package.json</code> 或 <code>.browserslistrc</code> 中配置。</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">browserslist</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> [</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#C3E88D;">&gt; 0.5%</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#C3E88D;">last 2 versions</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#C3E88D;">not dead</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#C3E88D;">not ie 11</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">  ]</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h2 id="与-swc、esbuild-对比" tabindex="-1">与 SWC、esbuild 对比 <a class="header-anchor" href="#与-swc、esbuild-对比" aria-label="Permalink to “与 SWC、esbuild 对比”">​</a></h2><p>随着 Rust/Go 编写的工具兴起，Babel 在纯语法转换的速度上不再有优势。</p><table tabindex="0"><thead><tr><th>对比维度</th><th>Babel</th><th>SWC</th><th>esbuild</th></tr></thead><tbody><tr><td>实现语言</td><td>JavaScript</td><td>Rust</td><td>Go</td></tr><tr><td>转译速度</td><td>慢</td><td>非常快（约 Babel 的 20 倍）</td><td>非常快</td></tr><tr><td>生态成熟度</td><td>插件极其丰富</td><td>快速增长，兼容 Babel 插件</td><td>较少</td></tr><tr><td>配置复杂度</td><td>较高</td><td>较低</td><td>低</td></tr><tr><td>自定义转换</td><td>强（插件 API 灵活）</td><td>支持</td><td>较弱</td></tr><tr><td>TypeScript 支持</td><td>仅 stripping</td><td>完整转换</td><td>仅 stripping</td></tr><tr><td>使用场景</td><td>需要自定义插件</td><td>Next.js 默认</td><td>Vite 依赖预构建</td></tr></tbody></table><h2 id="现代趋势" tabindex="-1">现代趋势 <a class="header-anchor" href="#现代趋势" aria-label="Permalink to “现代趋势”">​</a></h2><p>Babel 正在逐步被 SWC、esbuild 等基于编译型语言实现的工具替代，尤其是在纯语法转换场景：</p><ul><li><strong>Next.js</strong> 默认使用 SWC 替代 Babel，大幅提升编译速度</li><li><strong>Vite</strong> 开发阶段使用 esbuild 进行依赖预构建和 TS 转换</li><li><strong>Turbopack</strong> 使用 SWC 作为转译器</li></ul><p>然而，Babel 的<strong>插件生态</strong>仍然是其核心竞争力。许多高级转换（如 CSS-in-JS、国际化、代码优化）依赖 Babel 插件，这些是 SWC/esbuild 短期内难以完全替代的。此外，Babel 对 AST 的操作能力依然是编写自定义代码转换工具的首选。</p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h2><ul><li><a href="https://babeljs.io/" target="_blank" rel="noreferrer">Babel 官方文档</a></li><li><a href="https://github.com/babel/babel" target="_blank" rel="noreferrer">Babel GitHub 仓库</a></li><li><a href="https://github.com/zloirock/core-js" target="_blank" rel="noreferrer">core-js 文档</a></li><li><a href="https://github.com/browserslist/browserslist" target="_blank" rel="noreferrer">browserslist 文档</a></li><li><a href="https://swc.rs/" target="_blank" rel="noreferrer">SWC 官方文档</a></li></ul>`,34)])])}const y=a(o,[["render",n]]);export{F as __pageData,y as default};
